package limits

// Class distinguishes author refusals, operator ceilings and internal coordination budgets.
type Class uint8

// safety: scope determines who may configure a value without overriding an operator ceiling.
const (
	Author Class = iota
	Operator
	Internal
)

// Limit carries a typed value (duration, int64 bytes, or int count) with its documented enforcement.
type Limit struct {
	Name         string
	Value        any
	Class        Class
	Doc, Refusal string
}

